import {navigateWorkspace} from './workspace-navigation.mjs';
import {expect} from '@playwright/test';
export function readScopeURL(url){const u=new URL(url),search=u.hash?u.hash.slice(u.hash.indexOf('?')):u.search;return JSON.parse(new URLSearchParams(search).get('scope'));}
export async function exerciseQueryScope(page,{lang='zh',rows,normal,second,rule,openSecond,openPerson,screenshot}){
  const text=(zh,en)=>lang==='en'?en:zh,names=ids=>ids.map(id=>rows.find(p=>p.id===id).file_name).sort(),seen=async ids=>expect.poll(async()=>(await page.locator('.photo-caption>span').allTextContents()).sort()).toEqual(names(ids));
  const nav=name=>navigateWorkspace(page,name),bar=page.getByRole('region',{name:text('当前检索范围','Current search scope'),exact:true});
  const input=page.getByRole('textbox',{name:text('搜索照片','Search photos'),exact:true}),mode=page.getByRole('combobox',{name:text('搜索方式','Search mode'),exact:true});
  async function search(value){await mode.selectOption('text');await input.fill(value);await input.press('Enter');}
  async function open(name){await nav(text('影集','Albums'));await page.locator('.album-card').filter({hasText:name}).locator('.album-cover').click();}
  await open(normal.name);await seen(['a','b','c']);await expect(bar).toContainText(normal.name);expect(readScopeURL(page.url()).base).toEqual({album_id:normal.id});expect(await bar.innerText()).not.toContain(normal.id);
  await search('旅行');await seen(['a','b']);await input.fill('');await seen(['a','b','c']);await search('SONY');await seen(['a','c']);
  await page.getByRole('button',{name:text('筛选','Filter'),exact:true}).click();await page.locator('[data-facet=rating]').click();const pop=page.locator('.facet-popover');await pop.getByRole('checkbox',{name:/^0(?:\s|$)/}).check();await pop.getByRole('button',{name:text('关闭筛选','Close filter'),exact:true}).click();await seen(['a']);
  const clear=page.locator('.filter-chips').getByRole('button',{name:text('清除筛选','Clear Filters'),exact:true});await clear.click();await seen(['a','b','c']);await page.getByRole('button',{name:text('上次筛选','Last Filter'),exact:true}).click();await seen(['a']);await clear.click();await seen(['a','b','c']);await page.reload();await seen(['a','b','c']);await expect(bar).toContainText(normal.name);
  await openSecond();await seen(['b','c']);await expect(bar).toContainText(second.name);expect(readScopeURL(page.url()).base).toEqual({album_id:second.id});await expect(page.getByRole('button',{name:text('上次筛选','Last Filter'),exact:true})).toHaveCount(0);
  await page.goBack();await expect(page.locator('.albums-page')).toBeVisible();await page.goBack();await seen(['a','b','c']);await expect(bar).toContainText(normal.name);await page.goForward();await expect(page.locator('.albums-page')).toBeVisible();await page.goForward();await seen(['b','c']);await expect(bar).toContainText(second.name);
  await open(rule.name);await seen(['c','e']);const c=page.locator('.photo-card').filter({hasText:rows.find(p=>p.id==='c').file_name});await c.hover();const info=page.getByRole('complementary',{name:text('悬停照片信息','Hovered photo information'),exact:true});await expect(info).toBeVisible();await info.getByRole('button',{name:text('1 星','1 stars'),exact:true}).click();await seen(['e']);await info.getByRole('button',{name:text('关闭照片信息','Close photo information'),exact:true}).click();await expect(bar).toContainText(rule.name);
  if(openPerson){await openPerson();await seen(['b','c']);await expect(bar).toHaveAttribute('data-scope-origin','person');await search('SONY');await seen(['c']);await input.fill('');await seen(['b','c']);}
  if(screenshot)await page.screenshot({path:screenshot,fullPage:true});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await bar.getByRole('button',{name:text('返回全部照片','All photos'),exact:true}).click();await expect.poll(()=>readScopeURL(page.url()).base).toEqual({});await mode.selectOption('filename');await input.fill(rows.find(p=>p.id==='d').file_name);await input.press('Enter');await seen(['d']);
}
